MARC_LENGTH_POS = 5
logger = logging.getLogger('openlibrary.importapi')


class DataError(ValueError):
    pass


class BookImportError(Exception):
    def __init__(self, error_code, error='Invalid item', **kwargs):
        self.error_code = error_code
        self.error = error
        self.kwargs = kwargs


def parse_meta_headers(edition_builder):
    # parse S3-style http headers
    # we don't yet support augmenting complex fields like author or language
    # string_keys = ['title', 'title_prefix', 'description']

    re_meta = re.compile(r'HTTP_X_ARCHIVE_META(?:\d{2})?_(.*)')
    for k, v in web.ctx.env.items():
        m = re_meta.match(k)
        if m:
            meta_key = m.group(1).lower()
            edition_builder.add(meta_key, v, restrict_keys=False)


def parse_data(data: bytes) -> tuple[dict | None, str | None]:
    """
    Takes POSTed data and determines the format, and returns an Edition record
    suitable for adding to OL.

    :param bytes data: Raw data
    :return: (Edition record, format (rdf|opds|marcxml|json|marc)) or (None, None)
    """
    data = data.strip()
    if b'<?xml' in data[:10]:
        root = etree.fromstring(
            data, parser=lxml.etree.XMLParser(resolve_entities=False)
        )
        if root.tag == '{http://www.w3.org/1999/02/22-rdf-syntax-ns#}RDF':
            edition_builder = import_rdf.parse(root)
            format = 'rdf'
        elif root.tag == '{http://www.w3.org/2005/Atom}entry':
            edition_builder = import_opds.parse(root)
            format = 'opds'
        elif root.tag == '{http://www.loc.gov/MARC21/slim}record':
            if root.tag == '{http://www.loc.gov/MARC21/slim}collection':
                root = root[0]
            rec = MarcXml(root)
            edition = read_edition(rec)
            edition_builder = import_edition_builder.import_edition_builder(
                init_dict=edition
            )
            format = 'marcxml'
        else:
            raise DataError('unrecognized-XML-format')
    elif data.startswith(b'{') and data.endswith(b'}'):
        obj = json.loads(data)

        # Only look to the import_item table if a record is incomplete.
        # This is the minimum to achieve a complete record. See:
        # https://github.com/internetarchive/openlibrary/issues/9440
        # import_validator().validate() requires more fields.
        minimum_complete_fields = ["title", "authors", "publish_date"]
        is_complete = all(obj.get(field) for field in minimum_complete_fields)
        if not is_complete:
            isbn_10 = safeget(lambda: obj.get("isbn_10", [])[0])
            isbn_13 = safeget(lambda: obj.get("isbn_13", [])[0])
            identifier = to_isbn_13(isbn_13 or isbn_10 or "")

            if not identifier:
                identifier = get_non_isbn_asin(rec=obj)

            if identifier:
                supplement_rec_with_import_item_metadata(rec=obj, identifier=identifier)

        edition_builder = import_edition_builder.import_edition_builder(init_dict=obj)
        format = 'json'
    elif data[:MARC_LENGTH_POS].isdigit():
        # Marc Binary
        if len(data) < MARC_LENGTH_POS or len(data) != int(data[:MARC_LENGTH_POS]):
            raise DataError('no-marc-record')
        record = MarcBinary(data)
        edition = read_edition(record)
        edition_builder = import_edition_builder.import_edition_builder(
            init_dict=edition
        )
        format = 'marc'
    else:
        raise DataError('unrecognised-import-format')

    parse_meta_headers(edition_builder)
    return edition_builder.get_dict(), format


def supplement_rec_with_import_item_metadata(
    rec: dict[str, Any], identifier: str
) -> None:
    """
    Queries for a staged/pending row in `import_item` by identifier, and if found,
    uses select metadata to supplement empty fields in `rec`.

    Changes `rec` in place.
    """
    from openlibrary.core.imports import ImportItem  # Evade circular import.

    import_fields = [
        'authors',
        'description',
        'isbn_10',
        'isbn_13',
        'number_of_pages',
        'physical_format',
        'publish_date',
        'publishers',
        'title',
        'source_records',
    ]

    if import_item := ImportItem.find_staged_or_pending([identifier]).first():
        import_item_metadata = json.loads(import_item.get("data", '{}'))
        for field in import_fields:
            if field == "source_records":
                rec[field].extend(import_item_metadata.get(field))
            if not rec.get(field) and (staged_field := import_item_metadata.get(field)):
                rec[field] = staged_field


class importapi:
    """/api/import endpoint for general data formats."""

    def error(self, error_code, error='Invalid item', **kwargs):
        content = {'success': False, 'error_code': error_code, 'error': error}
        content.update(kwargs)
        raise web.HTTPError('400 Bad Request', data=json.dumps(content))

    def POST(self):
        web.header('Content-Type', 'application/json')
        if not can_write():
            raise web.HTTPError('403 Forbidden')

        data = web.data()

        try:
            edition, _ = parse_data(data)

        except (DataError, json.JSONDecodeError) as e:
            return self.error(str(e), 'Failed to parse import data')
        except ValidationError as e:
            return self.error('invalid-value', str(e).replace('\n', ': '))

        if not edition:
            return self.error('unknown-error', 'Failed to parse import data')

        try:
            reply = add_book.load(edition)
            # TODO: If any records have been created, return a 201, otherwise 200
            return json.dumps(reply)
        except add_book.RequiredField as e:
            return self.error('missing-required-field', str(e))
        except ClientException as e:
            return self.error('bad-request', **json.loads(e.json))
        except TypeError as e:
            return self.error('type-error', repr(e))
        except Exception as e:
            return self.error('unhandled-exception', repr(e))


def raise_non_book_marc(marc_record, **kwargs):
    details = 'Item rejected'
    # Is the item a serial instead of a monograph?
    marc_leaders = marc_record.leader()
    if marc_leaders[7] == 's':
        raise BookImportError('item-is-serial', details, **kwargs)

    # insider note: follows Archive.org's approach of
    # Item::isMARCXMLforMonograph() which excludes non-books
    # MARC leader$6,7 reference: https://www.loc.gov/marc/bibliographic/bdleader.html
    ACCEPTED_TYPES = 'am'  # a: Language material, m: Computer file
    if not (marc_leaders[6] in ACCEPTED_TYPES and marc_leaders[7] == 'm'):
        raise BookImportError('item-not-book', details, **kwargs)


class ia_importapi(importapi):
    """/api/import/ia import endpoint for Archive.org items, requiring an ocaid identifier rather than direct data upload.
    Request Format:

        POST /api/import/ia
        Content-Type: application/json
        Authorization: Basic base64-of-username:password

        {
            "identifier": "<ocaid>",
            "require_marc": "true",
            "bulk_marc": "false"
        }
    """

    @classmethod
    def ia_import(
        cls, identifier: str, require_marc: bool = True, force_import: bool = False
    ) -> str:
        """
        Performs logic to fetch archive.org item + metadata,
        produces a data dict, then loads into Open Library

        :param str identifier: archive.org ocaid
        :param bool require_marc: require archive.org item have MARC record?
        :param bool force_import: force import of this record
        :returns: the data of the imported book or raises  BookImportError
        """
        from_marc_record = False

        # Check 1 - Is this a valid Archive.org item?
        metadata = ia.get_metadata(identifier)
        if not metadata:
            raise BookImportError('invalid-ia-identifier', f'{identifier} not found')

        # Check 2 - Can the item be loaded into Open Library?
        status = ia.get_item_status(identifier, metadata)
        if status != 'ok' and not force_import:
            raise BookImportError(status, f'Prohibited Item {identifier}')

        # Check 3 - Does this item have a MARC record?
        marc_record = get_marc_record_from_ia(
            identifier=identifier, ia_metadata=metadata
        )
        if require_marc and not marc_record:
            raise BookImportError('no-marc-record')
        if marc_record:
            from_marc_record = True

            if not force_import:
                raise_non_book_marc(marc_record)
            try:
                edition_data = read_edition(marc_record)
            except MarcException as e:
                logger.error(f'failed to read from MARC record {identifier}: {e}')
                raise BookImportError('invalid-marc-record')
        else:
            try:
                edition_data = cls.get_ia_record(metadata)
            except KeyError:
                raise BookImportError('invalid-ia-metadata')
            except ValidationError as e:
                raise BookImportError('not-differentiable', str(e))

        # Add IA specific fields: ocaid, source_records, and cover
        edition_data = cls.populate_edition_data(edition_data, identifier)
        return cls.load_book(edition_data, from_marc_record)

    def POST(self):
        web.header('Content-Type', 'application/json')

        if not can_write():
            raise web.HTTPError('403 Forbidden')

        i = web.input()

        require_marc = i.get('require_marc') != 'false'
        force_import = i.get('force_import') == 'true'
        bulk_marc = i.get('bulk_marc') == 'true'

        if 'identifier' not in i:
            return self.error('bad-input', 'identifier not provided')
        identifier = i.identifier

        # First check whether this is a non-book, bulk-marc item
        if bulk_marc:
            # Get binary MARC by identifier = ocaid/filename:offset:length
            re_bulk_identifier = re.compile(r"([^/]*)/([^:]*):(\d*):(\d*)")
            try:
                ocaid, filename, offset, length = re_bulk_identifier.match(
                    identifier
                ).groups()
                data, next_offset, next_length = get_from_archive_bulk(identifier)
                next_data = {
                    'next_record_offset': next_offset,
                    'next_record_length': next_length,
                }
                rec = MarcBinary(data)
                edition = read_edition(rec)
            except MarcException as e:
                details = f'{identifier}: {e}'
                logger.error(f'failed to read from bulk MARC record {details}')
                return self.error('invalid-marc-record', details, **next_data)

            actual_length = int(rec.leader()[:MARC_LENGTH_POS])
            edition['source_records'] = 'marc:%s/%s:%s:%d' % (
                ocaid,
                filename,
                offset,
                actual_length,
            )

            local_id = i.get('local_id')
            if local_id:
                local_id_type = web.ctx.site.get('/local_ids/' + local_id)
                prefix = local_id_type.urn_prefix
                force_import = True
                id_field, id_subfield = local_id_type.id_location.split('$')

                def get_subfield(field, id_subfield):
                    if isinstance(field[1], str):
                        return field[1]
                    subfields = field[1].get_subfield_values(id_subfield)
                    return subfields[0] if subfields else None

                ids = [
                    get_subfield(f, id_subfield)
                    for f in rec.read_fields([id_field])
                    if f and get_subfield(f, id_subfield)
                ]
                edition['local_id'] = [f'urn:{prefix}:{id_}' for id_ in ids]

            # Don't add the book if the MARC record is a non-monograph item,
            # unless it is a scanning partner record and/or force_import is set.
            if not force_import:
                try:
                    raise_non_book_marc(rec, **next_data)

                except BookImportError as e:
                    return self.error(e.error_code, e.error, **e.kwargs)
            result = add_book.load(edition)

            # Add next_data to the response as location of next record:
            result.update(next_data)
            return json.dumps(result)

        try:
            return self.ia_import(
                identifier, require_marc=require_marc, force_import=force_import
            )
        except BookImportError as e:
            return self.error(e.error_code, e.error, **e.kwargs)

    @staticmethod
    def get_ia_record(metadata: dict) -> dict:
        """
        Generate Edition record from Archive.org metadata, in lieu of a MARC record

        :param dict metadata: metadata retrieved from metadata API
        :return: Edition record
        """
        authors = [{'name': name} for name in metadata.get('creator', '').split(';')]
        description = metadata.get('description')
        unparsed_isbns = metadata.get('isbn')
        language = metadata.get('language')
        lccn = metadata.get('lccn')
        subject = metadata.get('subject')
        oclc = metadata.get('oclc-id')
        imagecount = metadata.get('imagecount')
        unparsed_publishers = metadata.get('publisher')
        d = {
            'title': metadata.get('title', ''),
            'authors': authors,
            'publish_date': metadata.get('date'),
        }
        if description:
            d['description'] = description
        if unparsed_isbns:
            isbn_10, isbn_13 = get_isbn_10s_and_13s(unparsed_isbns)
            if isbn_10:
                d['isbn_10'] = isbn_10
            if isbn_13:
                d['isbn_13'] = isbn_13
        if language:
            if len(language) == 3:
                d['languages'] = [language]

            # Try converting the name of a language to its three character code.
            # E.g. English -> eng.
            else:
                try:
                    if lang_code := get_abbrev_from_full_lang_name(language):
                        d['languages'] = [lang_code]
                except LanguageMultipleMatchError as e:
                    logger.warning(

    if parsed_url.netloc.casefold() in (
        host.casefold() for host in allowed_cover_hosts
    ):
        return cover_url, edition

    return None, edition


def load_data(
    rec: dict,
    account_key: str | None = None,
    existing_edition: "Edition | None" = None,
):
    """
    Adds a new Edition to Open Library, or overwrites existing_edition with rec data.

    The overwrite option exists for cases where the existing edition data
    should be (nearly) completely overwritten by rec data. Revision 1 promise
    items are an example.

    Checks for existing Works.
    Creates a new Work, and Author, if required,
    otherwise associates the new Edition with the existing Work.

    :param dict rec: Edition record to add (no further checks at this point)
    :rtype: dict
    :return:
        {
            "success": False,
            "error": <error msg>
        }
      OR
        {
            "success": True,
            "work": {"key": <key>, "status": "created" | "modified" | "matched"},
            "edition": {"key": <key>, "status": "created"},
            "authors": [{"status": "matched", "name": "John Smith", "key": <key>}, ...]
        }
    """

    try:
        # get an OL style edition dict
        rec_as_edition = build_query(rec)
        edition: dict[str, Any]
        if existing_edition:
            # Note: This will overwrite any fields in the existing edition. This is ok for
            # now, because we'll really only come here when overwriting a promise
            # item
            edition = existing_edition.dict() | rec_as_edition

            # Preserve source_records to avoid data loss.
            edition['source_records'] = existing_edition.get(
                'source_records', []
            ) + rec.get('source_records', [])

            # Preserve existing authors, if any.
            if authors := existing_edition.get('authors'):
                edition['authors'] = authors

        else:
            edition = rec_as_edition

    except InvalidLanguage as e:
        return {
            'success': False,
            'error': str(e),
        }

    if not (edition_key := edition.get('key')):
        edition_key = web.ctx.site.new_key('/type/edition')

    cover_url, edition = process_cover_url(
        edition=edition, allowed_cover_hosts=ALLOWED_COVER_HOSTS
    )

    cover_id = None
    if cover_url:
        cover_id = add_cover(cover_url, edition_key, account_key=account_key)
    if cover_id:
        edition['covers'] = [cover_id]

    edits: list[dict] = []  # Things (Edition, Work, Authors) to be saved
    reply = {}
    # edition.authors may have already been processed by import_authors() in build_query(),
    # but not necessarily
    author_in = [
        (
            import_author(a, eastern=east_in_by_statement(rec, a))
            if isinstance(a, dict)
            else a
        )
        for a in edition.get('authors', [])
    ]
    # build_author_reply() adds authors to edits
    (authors, author_reply) = build_author_reply(
        author_in, edits, rec['source_records'][0]
    )

    if authors:
        edition['authors'] = authors
        reply['authors'] = author_reply

    work_key = safeget(lambda: edition['works'][0]['key'])
    work_state = 'created'
    # Look for an existing work
    if not work_key and 'authors' in edition:
        work_key = find_matching_work(edition)
    if work_key:
        work = web.ctx.site.get(work_key)
        work_state = 'matched'
        need_update = False
        for k in subject_fields:
            if k not in rec:
                continue
            for s in rec[k]:
                if normalize(s) not in [
                    normalize(existing) for existing in work.get(k, [])
                ]:
                    work.setdefault(k, []).append(s)
                    need_update = True
        if cover_id:
            work.setdefault('covers', []).append(cover_id)
            need_update = True
        if need_update:
            work_state = 'modified'
            edits.append(work.dict())
    else:
        # Create new work
        work = new_work(edition, rec, cover_id)
        work_state = 'created'
        work_key = work['key']
        edits.append(work)

    assert work_key
    if not edition.get('works'):
        edition['works'] = [{'key': work_key}]
    edition['key'] = edition_key
    edits.append(edition)

    comment = "overwrite existing edition" if existing_edition else "import new book"
    web.ctx.site.save_many(edits, comment=comment, action='add-book')

    # Writes back `openlibrary_edition` and `openlibrary_work` to
    # archive.org item after successful import:
    if 'ocaid' in rec:
        update_ia_metadata_for_ol_edition(edition_key.split('/')[-1])

    reply['success'] = True
    reply['edition'] = (
        {'key': edition_key, 'status': 'modified'}
        if existing_edition
        else {'key': edition_key, 'status': 'created'}
    )
    reply['work'] = {'key': work_key, 'status': work_state}
    return reply


def normalize_import_record(rec: dict) -> None:
    """
    Normalize the import record by:
        - Verifying required fields;
        - Ensuring source_records is a list;
        - Splitting subtitles out of the title field;
        - Cleaning all ISBN and LCCN fields ('bibids');
        - Deduplicate authors; and
        - Remove throw-away data used for validation.
        - Remove publication years of 1900 for AMZ/BWB/Promise.

        NOTE: This function modifies the passed-in rec in place.
    """
    required_fields = [
        'title',
        'source_records',
    ]  # ['authors', 'publishers', 'publish_date']
    for field in required_fields:
        if not rec.get(field):
            raise RequiredField(field)

    # Ensure source_records is a list.
    if not isinstance(rec['source_records'], list):
        rec['source_records'] = [rec['source_records']]

    publication_year = get_publication_year(rec.get('publish_date'))
    if publication_year and published_in_future_year(publication_year):
        del rec['publish_date']

    # Split subtitle if required and not already present
    if ':' in rec.get('title', '') and not rec.get('subtitle'):
        title, subtitle = split_subtitle(rec.get('title', ''))
        if subtitle:
            rec['title'] = title
            rec['subtitle'] = subtitle

    rec = normalize_record_bibids(rec)

    # deduplicate authors
    rec['authors'] = uniq(rec.get('authors', []), dicthash)

    # Validation by parse_data(), prior to calling load(), requires facially
    # valid publishers. If data are unavailable, we provide throw-away data
    # which validates. We use ["????"] as an override, but this must be
    # removed prior to import.
    if rec.get('publishers') == ["????"]:
        rec.pop('publishers')

    # Remove suspect publication dates from certain sources (e.g. 1900 from Amazon).
    if any(
        source_record.split(":")[0] in SOURCE_RECORDS_REQUIRING_DATE_SCRUTINY
        and rec.get('publish_date') in SUSPECT_PUBLICATION_DATES
        for source_record in rec['source_records']
    ):
        rec.pop('publish_date')


def validate_record(rec: dict) -> None:
    """
    Check for:
        - publication years too old from non-exempt sources (e.g. Amazon);
        - publish dates in a future year;
        - independently published books; and
        - books that need an ISBN and lack one.

    Each check raises an error or returns None.

    If all the validations pass, implicitly return None.
    """
    # Only validate publication year if a year is found.
    if publication_year := get_publication_year(rec.get('publish_date')):
        if publication_too_old_and_not_exempt(rec):
            raise PublicationYearTooOld(publication_year)
        elif published_in_future_year(publication_year):
            raise PublishedInFutureYear(publication_year)

    if is_independently_published(rec.get('publishers', [])):
        raise IndependentlyPublished

    if needs_isbn_and_lacks_one(rec):
        raise SourceNeedsISBN


def find_match(rec: dict, edition_pool: dict) -> str | None:
    """Use rec to try to find an existing edition key that matches."""
    return find_quick_match(rec) or find_threshold_match(rec, edition_pool)


def update_edition_with_rec_data(
    rec: dict, account_key: str | None, edition: "Edition"
) -> bool:
    """
    Enrich the Edition by adding certain fields present in rec but absent
    in edition.

    NOTE: This modifies the passed-in Edition in place.
    """
    need_edition_save = False
    # Add cover to edition
    if 'cover' in rec and not edition.get_covers():
        cover_url = rec['cover']
        cover_id = add_cover(cover_url, edition.key, account_key=account_key)
        if cover_id:
            edition['covers'] = [cover_id]
            need_edition_save = True

    # Add ocaid to edition (str), if needed
    if 'ocaid' in rec and not edition.ocaid:
        edition['ocaid'] = rec['ocaid']
        need_edition_save = True

    # Fields which have their VALUES added if absent.
    edition_list_fields = [
        'local_id',
        'lccn',
        'lc_classifications',
        'oclc_numbers',
        'source_records',
        'languages',
    ]
    edition_dict: dict = edition.dict()
    for field in edition_list_fields:
        if field not in rec:
            continue

        existing_values = edition_dict.get(field, []) or []
        rec_values = rec.get(field, [])

        # Languages in `rec` are ['eng'], etc., but import requires dict-style.
        if field == 'languages':
            formatted_languages = format_languages(languages=rec_values)
            supplemented_values = existing_values + [
                lang for lang in formatted_languages if lang not in existing_values
            ]
        else:
            case_folded_values = [v.casefold() for v in existing_values]
            supplemented_values = existing_values + [
                v for v in rec_values if v.casefold() not in case_folded_values
            ]

        if existing_values != supplemented_values:
            edition[field] = supplemented_values
            need_edition_save = True

    # Fields that are added as a whole if absent. (Individual values are not added.)
    other_edition_fields = [
        'description',
        'number_of_pages',
        'publishers',
        'publish_date',
    ]
    for f in other_edition_fields:
        if f not in rec or not rec[f]:
            continue
        if f not in edition:
            edition[f] = rec[f]
            need_edition_save = True

    # Add new identifiers (dict values, so different treatment from lists above.)
    if 'identifiers' in rec:
        identifiers = defaultdict(list, edition.dict().get('identifiers', {}))
        for k, vals in rec['identifiers'].items():
            identifiers[k].extend(vals)
            identifiers[k] = list(set(identifiers[k]))
        if edition.dict().get('identifiers') != identifiers:
            edition['identifiers'] = identifiers
            need_edition_save = True

    return need_edition_save


def update_work_with_rec_data(
    rec: dict, edition: "Edition", work: dict[str, Any], need_work_save: bool
) -> bool:
    """
    Enrich the Work by adding certain fields present in rec but absent
    in work.

    NOTE: This modifies the passed-in Work in place.
    """
    # Add subjects to work, if not already present
    if 'subjects' in rec:
        work_subjects: list[str] = list(work.get('subjects', []))
        rec_subjects: list[str] = rec.get('subjects', [])
        deduped_subjects = uniq(
            itertools.chain(work_subjects, rec_subjects), lambda item: item.casefold()
        )

        if work_subjects != deduped_subjects:
            work['subjects'] = deduped_subjects
            need_work_save = True

    # Add cover to work, if needed
    if not work.get('covers') and edition.get_covers():
        work['covers'] = [edition['covers'][0]]
        need_work_save = True

    # Add description to work, if needed
    if not work.get('description') and edition.get('description'):
        work['description'] = edition['description']
        need_work_save = True

    # Add authors to work, if needed
    if not work.get('authors'):
        authors = [import_author(a) for a in rec.get('authors', [])]
        work['authors'] = [
            {'type': {'key': '/type/author_role'}, 'author': a.get('key')}
            for a in authors
            if a.get('key')
        ]
        if work.get('authors'):
            need_work_save = True

    return need_work_save


def should_overwrite_promise_item(
    edition: "Edition", from_marc_record: bool = False
) -> bool:
    """
    Returns True for revision 1 promise items with MARC data available.

    Promise items frequently have low quality data, and MARC data is high
    quality. Overwriting revision 1 promise items with MARC data ensures
    higher quality records and eliminates the risk of obliterating human edits.
    """
    if edition.get('revision') != 1 or not from_marc_record:
        return False

    # Promise items are always index 0 in source_records.
    return bool(safeget(lambda: edition['source_records'][0], '').startswith("promise"))


def load(rec: dict, account_key=None, from_marc_record: bool = False) -> dict:
    """Given a record, tries to add/match that edition in the system.

    Record is a dictionary containing all the metadata of the edition.
    The following fields are mandatory:

        * title: str
        * source_records: list

    :param dict rec: Edition record to add
    :param bool from_marc_record: whether the record is based on a MARC record.
    :rtype: dict
    :return: a dict to be converted into a JSON HTTP response, same as load_data()
    """
    if not is_promise_item(rec):
        validate_record(rec)

    normalize_import_record(rec)

    # Resolve an edition if possible, or create and return one if not.
    edition_pool = build_pool(rec)
    if not edition_pool:
        # No match candidates found, add edition
        return load_data(rec, account_key=account_key)

    match = find_match(rec, edition_pool)
    if not match:
        # No match found, add edition
        return load_data(rec, account_key=account_key)

    # We have an edition match at this point
    need_work_save = need_edition_save = False
    work: dict[str, Any]
    existing_edition: Edition = web.ctx.site.get(match)

    # check for, and resolve, author redirects
    for a in existing_edition.authors:
        while is_redirect(a):
            if a in existing_edition.authors:
                existing_edition.authors.remove(a)
            a = web.ctx.site.get(a.location)
            if not is_redirect(a):
                existing_edition.authors.append(a)

    if existing_edition.get('works'):
        work = existing_edition.works[0].dict()
        work_created = False
    else:
        # Found an edition without a work
        work_created = need_work_save = need_edition_save = True
        work = new_work(existing_edition.dict(), rec)
        existing_edition.works = [{'key': work['key']}]

    # Send revision 1 promise item editions to the same pipeline as new editions
    # because we want to overwrite most of their data.
    if should_overwrite_promise_item(
        edition=existing_edition, from_marc_record=from_marc_record
    ):
        return load_data(
            rec, account_key=account_key, existing_edition=existing_edition
        )

    need_edition_save = update_edition_with_rec_data(
        rec=rec, account_key=account_key, edition=existing_edition
    )
    need_work_save = update_work_with_rec_data(
        rec=rec, edition=existing_edition, work=work, need_work_save=need_work_save
    )

    edits = []
    reply = {
        'success': True,
        'edition': {'key': match, 'status': 'matched'},
        'work': {'key': work['key'], 'status': 'matched'},
    }

    if need_edition_save:
        reply['edition']['status'] = 'modified'  # type: ignore[index]
        edits.append(existing_edition.dict())
    if need_work_save:
        reply['work']['status'] = 'created' if work_created else 'modified'  # type: ignore[index]
        edits.append(work)
    if edits:
        web.ctx.site.save_many(
            edits, comment='import existing book', action='edit-book'
        )
    if 'ocaid' in rec:
        update_ia_metadata_for_ol_edition(match.split('/')[-1])
    return reply


